-- Additive showroom upgrade. Old IDs, snapshots and projects are retained.
-- Only the original shipped catalog is archived; custom administrator models are untouched.
alter table public.templates drop constraint templates_style_check;
alter table public.templates add constraint templates_style_check check(style in ('minimalista','moderno','elegante','premium'));
update public.templates set active=false, slug='legacy-'||slug, content=content||jsonb_build_object('originalSlug',slug) where id::text like '10000000-0000-4000-8000-%';
update public.categories set active=false where slug in ('landing-pages','autonomos','personalizados');
