create or replace function private.valid_config(cfg jsonb,pid uuid) returns boolean language plpgsql stable security invoker set search_path = '' as $$
declare k text; v text;
begin
  if cfg is null or jsonb_typeof(cfg) is distinct from 'object' or octet_length(cfg::text)>60000 then return false; end if;
  foreach k in array array['company','slogan','primary','secondary','background','buttonColor','font','title','subtitle','description','email','phone','address','instagram','cta','logo','heroImage','notes'] loop
    if jsonb_typeof(cfg->k) is distinct from 'string' then return false; end if;
  end loop;
  if cfg->'version' is distinct from '1'::jsonb or cfg->>'font' not in ('sans','serif','mono') then return false; end if;
  if length(trim(cfg->>'company')) not between 1 and 200 or length(trim(cfg->>'title')) not between 1 and 200
    or length(cfg->>'description')>4000 or length(cfg->>'notes')>8000 or length(cfg->>'address')>500 or length(cfg->>'phone')>30 or length(cfg->>'instagram')>100 then return false; end if;
  foreach k in array array['slogan','subtitle','cta'] loop if length(cfg->>k)>200 then return false; end if; end loop;
  foreach k in array array['primary','secondary','background','buttonColor','textColor','highlight'] loop if (cfg ? k) and cfg->>k !~ '^#[0-9a-fA-F]{6}$' then return false; end if; end loop;
  foreach k in array array['textColor','highlight'] loop if cfg ? k and (jsonb_typeof(cfg->k) is distinct from 'string' or cfg->>k !~ '^#[0-9a-fA-F]{6}$') then return false; end if; end loop;
  if cfg->>'email'<>'' and (length(cfg->>'email')>320 or cfg->>'email' !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$') then return false; end if;
  if jsonb_typeof(cfg->'radius') is distinct from 'number' or cfg->>'radius' !~ '^[0-9]{1,2}$' or (cfg->>'radius')::int not between 0 and 32 then return false; end if;
  if jsonb_typeof(cfg->'pages') is distinct from 'number' or cfg->>'pages' !~ '^[0-9]{1,3}$' or (cfg->>'pages')::int not between 1 and 100 then return false; end if;
  foreach k in array array['services','sections','features','images'] loop
    if jsonb_typeof(cfg->k) is distinct from 'array' then return false; end if;
    if jsonb_array_length(cfg->k)>30 then return false; end if;
    if exists(select 1 from jsonb_array_elements(cfg->k) as elem where jsonb_typeof(elem) is distinct from 'string' or length(elem#>>'{}')>250) then return false; end if;
  end loop;
  if jsonb_array_length(cfg->'images')>12 or jsonb_array_length(cfg->'services')>20 or jsonb_array_length(cfg->'sections')>7 then return false; end if;
  if exists(select 1 from jsonb_array_elements_text(cfg->'sections') as section_value where section_value not in ('sobre','servicos','galeria','depoimentos','equipe','faq','contato')) then return false; end if;
  for v in select cfg->>'logo' union all select cfg->>'heroImage' union all select jsonb_array_elements_text(cfg->'images') loop
    if v ~ '^/api/catalog-assets/[0-9a-f-]{36}\.(jpg|png|webp)$' then continue; end if;
    if v<>'' and v !~ '^/images/[a-z-]+\.(svg|webp)$' then
      if v !~ '^/api/files/[0-9a-f-]{36}\?inline=1$' then return false; end if;
      if not exists(select 1 from public.files where id=split_part(split_part(v,'/',4),'?',1)::uuid and project_id=pid and purpose='asset' and mime like 'image/%') then return false; end if;
    end if;
  end loop;
  return true;
exception when invalid_text_representation then return false;
end; $$;
revoke all on function private.valid_config(jsonb,uuid) from public,anon,authenticated;


-- Enforce price hierarchy in the database as well as the administrative form.
create function private.validate_catalog_pricing() returns trigger language plpgsql security invoker set search_path='' as $$
declare price bigint; boundary bigint;
begin
  if coalesce(new.content->>'tier','conventional') not in ('conventional','premium') then raise exception 'Classificação inválida.'; end if;
  if coalesce(new.content->>'basePriceCents','')='' then return new; end if;
  if new.content->>'basePriceCents' !~ '^[0-9]{1,9}$' then raise exception 'Preço-base inválido.'; end if;
  price:=(new.content->>'basePriceCents')::bigint;
  if price<100 or price>100000000 then raise exception 'Preço-base inválido.'; end if;
  if not new.active then return new; end if;
  perform pg_catalog.pg_advisory_xact_lock(918421::bigint);
  if new.content->>'tier'='premium' then
    select max((content->>'basePriceCents')::bigint) into boundary from public.templates where id<>new.id and active and coalesce(content->>'tier','conventional')='conventional' and coalesce(content->>'basePriceCents','')~'^[0-9]{1,9}$';
    if price<=boundary then raise exception 'O preço-base Premium deve superar os valores convencionais configurados.'; end if;
  else
    select min((content->>'basePriceCents')::bigint) into boundary from public.templates where id<>new.id and active and content->>'tier'='premium' and coalesce(content->>'basePriceCents','')~'^[0-9]{1,9}$';
    if price>=boundary then raise exception 'O preço convencional deve ficar abaixo dos valores Premium configurados.'; end if;
  end if;
  return new;
end; $$;
revoke all on function private.validate_catalog_pricing() from public,anon,authenticated;
create trigger validate_catalog_pricing before insert or update on public.templates for each row execute function private.validate_catalog_pricing();
